(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.28)*18 + Math.cos(y*0.013-t*0.19)*12 + Math.sin((x+y)*0.008+t*0.15)*8;
  const w1y = Math.cos(y*0.02-t*0.22)*18 + Math.sin(x*0.016+t*0.31)*12 + Math.cos((x-y)*0.009-t*0.18)*8;
  const w2x = Math.sin(w1x*0.025+t*0.4)*6 + Math.cos(w1y*0.02-t*0.35)*5;
  const w2y = Math.cos(w1y*0.025-t*0.38)*6 + Math.sin(w1x*0.022+t*0.42)*5;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.8],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.2],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.1],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.7],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65)*50, 0.11, 2.1, 1.3],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75+4)*40, 0.085, 1.8, 0.85]
  ];
  let aS = 0, iS = 0, cS = 0;
  for (const [sX, sY, f, sp, wt] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp) * wt;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) * wt;
    cS += Math.sin(d*f*1.3 - t*sp*0.8 + 3.0) * wt;
  }
  const wSum = src.reduce((s, r) => s+r[4], 0);
  const act = aS/wSum, inh = iS/wSum, cat = cS/wSum;
  const bg = (Math.sin(sx*0.035+sy*0.022+t*0.75) + Math.sin(sx*0.028-sy*0.038+t*1.05))/2
    + Math.sin((sx+sy)*0.11+t*2.3)*0.2 + Math.sin((sx-sy)*0.095-t*1.8)*0.2
    + Math.sin(sx*0.06+sy*0.08-t*1.5)*0.15;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.045-ang*3.5-t*1.4) + Math.sin(dist*0.035+ang*4.5-t*1.1)
    + Math.sin(dist*0.06-ang*2-t*2.0))*0.3;
  const lap = (Math.sin(sx*0.14+sy*0.1+t*0.9) + Math.sin(sx*0.1-sy*0.14-t*0.7) + Math.sin(sx*0.18+t*1.2))*0.33;
  const reaction1 = Math.tanh((act - inh*0.7 + bg*0.25 + spiral)*2.2);
  const reaction2 = Math.tanh((cat*0.6 - act*0.4 + lap*0.3 + spiral*0.5)*1.8);
  const coupled = Math.tanh(reaction1*0.65 + reaction2*0.35 + Math.sin(reaction1*reaction2*3+t)*0.15);
  const cell = Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14) + Math.sin((sx+sy)*0.095+t)*0.5
    + Math.sin(sx*0.07)*Math.cos(sy*0.11-t*0.5))*1.5)*0.25;
  const micro = Math.sin(sx*0.3+sy*0.25-t*3)*Math.sin(sx*0.2-sy*0.35+t*2.5)*0.12;
  const blend = coupled*0.65 + cell*0.2 + micro*0.15;
  const v = blend*0.5+0.5;
  const pal = [
    [5,12,52],[8,35,85],[12,65,115],[18,110,135],[30,155,140],[120,175,110],
    [195,185,65],[220,155,55],[215,110,60],[185,65,65],[120,35,55],[60,18,48],[5,12,52]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const sm = f*f*(3-2*f);
  const pulse = 0.85 + Math.sin(coupled*Math.PI)*0.15;
  const edge = Math.abs(coupled)>0.65 ? 1.12 + Math.abs(coupled)*0.06 : 0.92 + Math.abs(coupled)*0.08;
  const glow = Math.max(0, coupled)*0.08;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*sm)*pulse*edge + glow*80)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*sm)*pulse*edge + glow*40)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*sm)*pulse*edge + glow*120)|0)
  ];
}
